const incoming = $input.first()?.json;
const safeIncoming =
  incoming && typeof incoming === 'object' && !Array.isArray(incoming)
    ? incoming
    : {};

return [
  {
    json: {
      ...safeIncoming,
      cv_motion_summary: {
        video_id: "sign_reference",
        frames_total: 332,
        pose_detection_rate_percent: 100.0,
        hand_detection_rate_percent: 93.98,
        missing_hand_frames: 20,
        motion_representation_status: "MOTION_REPRESENTATION_PARTIAL",
        technical_interpretation:
          "The reference video can be converted into structured motion data for further experimentation, but motion fidelity and professional sign correctness are not proven.",
        limitations: [
          "Single adult reference video",
          "No professional sign correctness validation",
          "No avatar generation",
          "No synthetic-video fidelity test",
        ],
      },
    },
  },
];

const item = $input.first()?.json ?? {};
const sign = item.sign;
const cv = item.cv_motion_summary;
const failedChecks = [];

if (!sign || typeof sign !== 'object' || Array.isArray(sign)) {
  failedChecks.push({
    check: 'approved_sign_object',
    detail: 'Approved sign object is missing or is not a JSON object.',
  });
} else {
  for (const field of ['sign_id', 'sign_name', 'source_id', 'approved_description']) {
    if (typeof sign[field] !== 'string' || !sign[field].trim()) {
      failedChecks.push({
        check: field,
        detail: field + ' must be a non-empty string.',
      });
    }
  }

  if (!Object.prototype.hasOwnProperty.call(sign, 'movement_notes') ||
      typeof sign.movement_notes !== 'string') {
    failedChecks.push({
      check: 'movement_notes',
      detail: 'movement_notes must exist and be a string.',
    });
  }

  if (!Array.isArray(sign.do_not_claim)) {
    failedChecks.push({
      check: 'do_not_claim',
      detail: 'do_not_claim must exist and be an array.',
    });
  }

  if (sign.requires_human_review !== true) {
    failedChecks.push({
      check: 'requires_human_review',
      detail: 'requires_human_review must be true.',
    });
  }
}

if (!cv || typeof cv !== 'object' || Array.isArray(cv)) {
  failedChecks.push({
    check: 'cv_motion_summary',
    detail: 'cv_motion_summary is missing or is not a JSON object.',
  });
} else if (
  typeof cv.motion_representation_status !== 'string' ||
  !cv.motion_representation_status.trim()
) {
  failedChecks.push({
    check: 'motion_representation_status',
    detail: 'cv_motion_summary.motion_representation_status must exist.',
  });
}

if (failedChecks.length) {
  return [
    {
      json: {
        ...item,
        schema_check: {
          passed: false,
          failed_checks: failedChecks,
        },
        workflow_status: 'draft_rejected_by_schema_check',
        automatic_publication: false,
      },
    },
  ];
}

return [
  {
    json: {
      ...item,
      schema_check: {
        passed: true,
        failed_checks: [],
      },
    },
  },
];

const source = $('Schema Check').first().json.sign;
const raw = $json.text ?? $json.output ?? $json.response ?? $json;
let draft;
try {
  draft = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  return [{ json: { draft: null, quality_gate: { passed: false, failed_checks: [{ check: 'valid_json', detail: error.message }], warnings: [] } } }];
}
const required = ['sign_id','source_id','review_status','requires_human_review','parent_title','short_explanation','when_to_use','practice_tip','school_home_connection','motion_note','boundaries'];
const failed = [];
const missing = required.filter((field) => !(field in draft));
if (missing.length) failed.push({ check: 'required_fields_present', detail: 'Missing: ' + missing.join(', ') });
if (draft.requires_human_review !== true) failed.push({ check: 'human_review_required', detail: 'requires_human_review must be true' });
if (draft.review_status !== 'draft_requires_professional_approval') failed.push({ check: 'review_status_preserved', detail: 'Invalid review_status' });
if (draft.sign_id !== source.sign_id) failed.push({ check: 'sign_id_preserved', detail: 'sign_id changed' });
if (draft.source_id !== source.source_id) failed.push({ check: 'source_id_preserved', detail: 'source_id changed' });
const text = JSON.stringify(draft);
const banned = [/\baccelerate\b/i,/\baccelerated\b/i,/\bboost\s+language\b/i,/\btreat(?:s|ed|ing)?\s+(?:a\s+)?(?:communication\s+)?delay/i,/\bdiagnos(?:e|es|ed|ing|is|tic)\b/i,/\btherapy\b/i,/\bcure(?:s|d|ing)?\b/i,/\bASL\b/i,/\bLSE\b/i];
if (banned.some((pattern) => pattern.test(text))) failed.push({ check: 'banned_claims_absent', detail: 'Banned claim or term detected' });
const fallback = 'Movement instructions are unavailable in the approved input; use an approved reference only after professional review.';
const expectedMotion = (source.movement_notes || '').trim() || fallback;
if (draft.motion_note !== expectedMotion) failed.push({ check: 'movement_note_source_adherence', detail: 'motion_note differs from approved source or fallback' });
const warnings = source.movement_notes?.trim() ? [] : ['Approved movement_notes are missing; fixed fallback required.'];
return [{ json: { draft, quality_gate: { passed: failed.length === 0, failed_checks: failed, warnings } } }];
